css:
/* From Uiverse.io by mi-series - Tags: form, password, forgot password */
.__UIV_SCOPE__ .forgot-password {
  background-color: #E8EAE3;
  max-width: 450px;
  border-radius: 10px;
  padding: 20px;
  color: #000;
  box-shadow: 0px 87px 78px -39px rgba(0,0,0,0.4);
}

.__UIV_SCOPE__ .header {
  text-align: center;
  margin-top: 0.75rem;
}

.__UIV_SCOPE__ .forgot-password .title {
  font-size: 1.875rem;
  font-weight: 700;
  line-height: 1.25rem;
  color: rgba(0, 0, 0, 1);
}

.__UIV_SCOPE__ .forgot-password .sub-title {
  margin-top: 0.4rem;
  font-size: 1rem;
  line-height: 1.5rem;
}

.__UIV_SCOPE__ .reset-option {
  margin-top: 1rem;
  margin-bottom: 15px;
}

.__UIV_SCOPE__ .reset-option label {
  cursor: pointer;
  overflow: hidden;
  border: 2px solid rgba(229, 231, 235, 1);
  border-radius: 0.375rem;
  background-color: #F7F7F7;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem .4rem;
  margin: 10px 0;
  transform: all .15s ease;
}

.__UIV_SCOPE__ .reset-option label .reset-info {
  display: flex;
  flex-direction: column;
  margin-left: 10px;
}

.__UIV_SCOPE__ .reset-title {
  font-size: 1.25rem;
  line-height: 1.75rem;
  font-weight: 600;
  color: rgba(0, 0, 0, 1);
}

.__UIV_SCOPE__ .reset-sub-title {
  font-size: 0.875rem;
  line-height: 1.25rem;
}

.__UIV_SCOPE__ .reset-option input:checked + label {
  border-color: #FA2742;
}

.__UIV_SCOPE__ .send-btn {
  text-decoration: none;
  width: 100%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 0.375rem;
  background-color: #FA2742;
  padding: 1rem 3rem;
  font-weight: 600;
  color: #000;
  transform: all .15s ease;
}

.__UIV_SCOPE__ .send-btn:hover {
  opacity: .9;
}

.__UIV_SCOPE__ .reset-option input {
  display: none;
}

.__UIV_SCOPE__ .resend {
  color: #FA2742;
  font-weight: 600;
}
